CREATE TYPE "StaffStatus" AS ENUM ('INVITED', 'ACTIVE', 'ON_LEAVE', 'SUSPENDED', 'TERMINATED', 'RESIGNED');
CREATE TYPE "StaffEmploymentType" AS ENUM ('FULL_TIME', 'PART_TIME', 'CONTRACT', 'VISITING', 'INTERN');
CREATE TYPE "StaffDocumentStatus" AS ENUM ('PENDING', 'VERIFIED', 'REJECTED', 'EXPIRED');
CREATE TYPE "StaffDocumentType" AS ENUM ('IDENTITY_PROOF', 'ADDRESS_PROOF', 'EDUCATION_CERTIFICATE', 'EXPERIENCE_LETTER', 'CONTRACT', 'APPOINTMENT_LETTER', 'POLICE_VERIFICATION', 'MEDICAL', 'OTHER');
CREATE TABLE "StaffDepartment" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "StaffDesignation" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"isTeachingRole" BOOLEAN NOT NULL DEFAULT FALSE,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "StaffMember" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"employeeNumber" TEXT NOT NULL,"firstName" TEXT NOT NULL,"middleName" TEXT,"lastName" TEXT,"preferredName" TEXT,"email" TEXT,"phone" TEXT,"alternatePhone" TEXT,"dateOfBirth" DATE,"gender" TEXT,"nationality" TEXT,"address" JSONB,"departmentId" TEXT,"designationId" TEXT,"employmentType" "StaffEmploymentType" NOT NULL DEFAULT 'FULL_TIME',"status" "StaffStatus" NOT NULL DEFAULT 'INVITED',"dateOfJoining" DATE,"dateOfLeaving" DATE,"emergencyContactName" TEXT,"emergencyContactPhone" TEXT,"userId" TEXT,"notes" TEXT,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "StaffEmploymentHistory" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"staffMemberId" TEXT NOT NULL,"departmentId" TEXT,"designationId" TEXT,"employmentType" "StaffEmploymentType" NOT NULL,"startsOn" DATE NOT NULL,"endsOn" DATE,"notes" TEXT,"recordedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TeacherAssignment" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"staffMemberId" TEXT NOT NULL,"academicYearId" TEXT NOT NULL,"gradeLevelId" TEXT NOT NULL,"sectionName" TEXT NOT NULL,"curriculumSubjectId" TEXT,"isClassTeacher" BOOLEAN NOT NULL DEFAULT FALSE,"startsOn" DATE,"endsOn" DATE,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "StaffDocument" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"staffMemberId" TEXT NOT NULL,"documentType" "StaffDocumentType" NOT NULL,"displayName" TEXT NOT NULL,"objectKey" TEXT NOT NULL,"mimeType" TEXT,"sizeBytes" BIGINT,"issuedAt" DATE,"expiresAt" DATE,"status" "StaffDocumentStatus" NOT NULL DEFAULT 'PENDING',"reviewNotes" TEXT,"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"uploadedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StaffAuditEvent" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"staffMemberId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"actorUserId" TEXT NOT NULL,"beforeData" JSONB,"afterData" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX "StaffDepartment_school_code_key" ON "StaffDepartment"("schoolId","code");
CREATE UNIQUE INDEX "StaffDepartment_tenant_id_key" ON "StaffDepartment"("id","organizationId","schoolId");
CREATE UNIQUE INDEX "StaffDesignation_school_code_key" ON "StaffDesignation"("schoolId","code");
CREATE UNIQUE INDEX "StaffDesignation_tenant_id_key" ON "StaffDesignation"("id","organizationId","schoolId");
CREATE UNIQUE INDEX "StaffMember_school_employeeNumber_key" ON "StaffMember"("schoolId","employeeNumber");
