CREATE UNIQUE INDEX "CurriculumSubject_tenant_id_key" ON "CurriculumSubject"("id","organizationId","schoolId");
CREATE INDEX "StaffMember_tenant_status_idx" ON "StaffMember"("organizationId","schoolId","status");
CREATE INDEX "StaffMember_name_idx" ON "StaffMember"("schoolId","lastName","firstName");
CREATE INDEX "StaffHistory_member_idx" ON "StaffEmploymentHistory"("organizationId","schoolId","staffMemberId","startsOn");
CREATE INDEX "TeacherAssignment_class_idx" ON "TeacherAssignment"("organizationId","schoolId","academicYearId","gradeLevelId","sectionName");
CREATE INDEX "StaffDocument_type_idx" ON "StaffDocument"("organizationId","schoolId","staffMemberId","documentType");
CREATE INDEX "StaffAudit_member_idx" ON "StaffAuditEvent"("organizationId","schoolId","staffMemberId","createdAt");
